using System;
using System.Collections.Generic;

namespace TameableAnimals
{
    /// <summary>
    /// Generado con las mallas del juego (scratchpad/make_rein_masks.py): píxeles de la textura de cada montura que
    /// usan solo las piezas de la cabeza (brida, correas). Un bit por píxel, filas desde abajo (como GetPixels).
    /// Se precalculan porque las mallas de estas monturas no se pueden leer desde el juego.
    /// </summary>
    internal static class ReinMasks
    {
        private static readonly Dictionary<string, (int Width, int Height, string Bits)> s_data = new Dictionary<string, (int, int, string)>
        {
            ["SaddleMoose"] = (128, 128, ""),
            ["SaddleAsksvin"] = (128, 128, ""),
        };

        /// <summary>Máscara para la textura indicada, o null si no hay o el tamaño no coincide.</summary>
        internal static bool[] Get(string itemPrefabName, int width, int height)
        {
            if (!s_data.TryGetValue(itemPrefabName, out var data) || data.Width != width || data.Height != height)
            {
                return null;
            }
            byte[] bytes = Convert.FromBase64String(data.Bits);
            var mask = new bool[width * height];
            for (int i = 0; i < mask.Length; i++)
            {
                mask[i] = (bytes[i >> 3] >> (i & 7) & 1) != 0;
            }
            return mask;
        }
    }
}
